import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
// Single inline schema defining all customizable parameters


export type GearAnimationProps = Record<string, any>;

// Helper to generate the SVG path data for a gear programmatically
const createGearPath = (
  radius: number,
  teeth: number,
  toothDepth: number,
  holeRadius: number
) => {
  const baseRadius = radius - toothDepth;
  const toothAngle = (Math.PI * 2) / teeth;
  let d = "";

  for (let i = 0; i < teeth; i++) {
    const startAngle = i * toothAngle;
    
    // Proportions to create the flat-topped, chamfered gear teeth seen in the reference
    const valleyEnd = startAngle + toothAngle * 0.15;
    const riseEnd = startAngle + toothAngle * 0.35;
    const topEnd = startAngle + toothAngle * 0.65;
    const fallEnd = startAngle + toothAngle * 0.85;

    // Valley start
    const v1x = Math.cos(startAngle) * baseRadius;
    const v1y = Math.sin(startAngle) * baseRadius;
    if (i === 0) d += `M ${v1x} ${v1y} `;
    else d += `L ${v1x} ${v1y} `;

    // Sequence tracing one tooth
    d += `L ${Math.cos(valleyEnd) * baseRadius} ${Math.sin(valleyEnd) * baseRadius} `;
    d += `L ${Math.cos(riseEnd) * radius} ${Math.sin(riseEnd) * radius} `;
    d += `L ${Math.cos(topEnd) * radius} ${Math.sin(topEnd) * radius} `;
    d += `L ${Math.cos(fallEnd) * baseRadius} ${Math.sin(fallEnd) * baseRadius} `;
  }
  d += "Z ";

  // Cutout hole in the center (drawn counter-clockwise for evenodd fill rule)
  if (holeRadius > 0) {
    d += `M ${holeRadius} 0 `;
    d += `A ${holeRadius} ${holeRadius} 0 1 0 ${-holeRadius} 0 `;
    d += `A ${holeRadius} ${holeRadius} 0 1 0 ${holeRadius} 0 `;
    d += "Z";
  }

  return d;
};

// Reusable Gear Component
const Gear: React.FC<{
  size: number;
  teeth: number;
  toothDepthRatio: number;
  holeRatio: number;
  color: string;
  isOutline?: boolean;
  strokeWidth?: number;
}> = ({ size, teeth, toothDepthRatio, holeRatio, color, isOutline, strokeWidth = 10 }) => {
  const radius = size / 2;
  
  // Shrink outer radius slightly if it's an outline so the stroke doesn't clip the SVG bounds
  const safeRadius = isOutline ? radius - strokeWidth / 2 : radius;
  const toothDepth = safeRadius * toothDepthRatio;
  const holeRadius = safeRadius * holeRatio;
  
  // Memoize path generation to save processing time per frame
  const d = useMemo(() => {
     return createGearPath(safeRadius, teeth, toothDepth, holeRadius);
  }, [safeRadius, teeth, toothDepth, holeRadius]);

  return (
    <svg 
      width={size} 
      height={size} 
      viewBox={`-${size/2} -${size/2} ${size} ${size}`} 
      style={{ overflow: 'visible', display: 'block', transition: "none" }}
    >
      <path 
        d={d} 
        fill={isOutline ? "transparent" : color} 
        stroke={isOutline ? color : "none"} 
        strokeWidth={isOutline ? strokeWidth : 0}
        fillRule="evenodd"
        strokeLinejoin="round"
        strokeLinecap="round"
        style={{ transition: "none" }}
      />
    </svg>
  );
};

// Main Animation Component
const GearAnimation: React.FC<GearAnimationProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 5,
  largeGearColor = "#1073b0",
  largeGearSize = 0.65,
  largeGearX = 0.18,
  largeGearY = -0.18,
  mediumGearColor = "#00b4f0",
  mediumGearSize = 0.45,
  mediumGearX = -0.32,
  mediumGearY = 0.02,
  smallGearColor = "#ffffff",
  smallGearSize = 0.35,
  smallGearX = 0.0,
  smallGearY = 0.25,
  rotationSpeed = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to handle transparent background correctly
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Staggered pop-in springs for the "appear one by one" request
  const scaleSpring1 = spring({ frame: frame - 0, fps, config: { damping: 12, mass: 0.8 } });
  const scaleSpring2 = spring({ frame: frame - 15, fps, config: { damping: 12, mass: 0.8 } });
  const scaleSpring3 = spring({ frame: frame - 30, fps, config: { damping: 12, mass: 0.8 } });

  // Entrance twist interpolation to make them spin dynamically as they pop in
  const entranceRot1 = interpolate(frame, [0, 30], [-90, 0], { extrapolateRight: 'clamp' });
  const entranceRot2 = interpolate(frame, [15, 45], [90, 0], { extrapolateRight: 'clamp' });
  const entranceRot3 = interpolate(frame, [30, 60], [-90, 0], { extrapolateRight: 'clamp' });

  // Responsive scaling constraints based on 16:9 canvas
  const cx = width / 2;
  const cy = height / 2;
  const s = Math.min(width, height);

  // Layout positions & sizes configured by props
  const lgSize = s * largeGearSize;
  const lgX = cx + s * largeGearX;
  const lgY = cy + s * largeGearY;

  const mdSize = s * mediumGearSize;
  const mdX = cx + s * mediumGearX;
  const mdY = cy + s * mediumGearY;

  const smSize = s * smallGearSize;
  const smX = cx + s * smallGearX;
  const smY = cy + s * smallGearY;

  // Continuous interlocking rotation math (inverse speeds for adjacent gears)
  const baseRot = frame * rotationSpeed * 1.5;
  const rot1 = baseRot + entranceRot1;
  const rot2 = -baseRot * (lgSize / mdSize) + 12 + entranceRot2; // Initial offset to align teeth
  const rot3 = baseRot * (lgSize / smSize) - 8 + entranceRot3;   // Initial offset to align teeth

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      
      {/* Medium Gear */}
      <div
        style={{
          position: 'absolute',
          left: mdX - mdSize / 2,
          top: mdY - mdSize / 2,
          width: mdSize,
          height: mdSize,
          transform: `scale(${scaleSpring2}) rotate(${rot2}deg)`,
          transformOrigin: 'center center',
          transition: "none",
        }}
      >
        <Gear 
          size={mdSize} 
          teeth={10} 
          toothDepthRatio={0.15} 
          holeRatio={0.35} 
          color={mediumGearColor} 
        />
      </div>

      {/* Large Gear */}
      <div
        style={{
          position: 'absolute',
          left: lgX - lgSize / 2,
          top: lgY - lgSize / 2,
          width: lgSize,
          height: lgSize,
          transform: `scale(${scaleSpring1}) rotate(${rot1}deg)`,
          transformOrigin: 'center center',
          transition: "none",
        }}
      >
        <Gear 
          size={lgSize} 
          teeth={12} 
          toothDepthRatio={0.12} 
          holeRatio={0.4} 
          color={largeGearColor} 
        />
      </div>

      {/* Small Gear */}
      <div
        style={{
          position: 'absolute',
          left: smX - smSize / 2,
          top: smY - smSize / 2,
          width: smSize,
          height: smSize,
          transform: `scale(${scaleSpring3}) rotate(${rot3}deg)`,
          transformOrigin: 'center center',
          transition: "none",
        }}
      >
        <Gear 
          size={smSize} 
          teeth={7} 
          toothDepthRatio={0.18} 
          holeRatio={0.35} 
          color={smallGearColor} 
          isOutline 
          strokeWidth={Math.max(2, s * 0.025)} 
        />
      </div>

    </AbsoluteFill>
  );
};

export default GearAnimation;